<script lang="ts">
    import {
        analysisResult,
        patientMetadata,
        uploadedFileUrls,
    } from "$lib/stores.js";
    import { Button } from "$lib/components/ui/button/index.js";
    import { Badge } from "$lib/components/ui/badge/index.js";
    import { Separator } from "$lib/components/ui/separator/index.js";
    import * as Item from "$lib/components/ui/item/index.js";

    import { Progress } from "$lib/components/ui/progress/index.js";
    import * as Tooltip from "$lib/components/ui/tooltip/index.js";
    import * as Slider from "$lib/components/ui/slider/index.js";
    import { Label } from "$lib/components/ui/label/index.js";
    import { Chat } from "$lib/components/ui/chat/index.js";

    import { goto } from "$app/navigation";
    import { Stethoscope, FileDigit, Undo2, RotateCcw } from "lucide-svelte";
    import "../../app.css";
    import CornerstoneViewport from "./cornerstone-viewport.svelte";
    import ImageBar from "./image-bar.svelte";
    import HeatmapBar from "./heatmap-bar.svelte";
    import type { Prediction, ImageResult } from "$lib/types.js";

    const defaultResult = {
        status: "success",
        analysis: {
            model_version: "v1.0",
            predictions: [
                {
                    class: "Pneumonia",
                    confidence: 0.92,
                    reason: "Strong evidence of pneumonia detected with bilateral opacities in the lower lobes.",
                },
                {
                    class: "Effusion",
                    confidence: 0.88,
                    reason: "Moderate evidence of pleural effusion with fluid accumulation visible.",
                },
            ],
            image_results: [
                {
                    index: 0,
                    filename: "example1.png",
                    predictions: [
                        {
                            class: "Pneumonia",
                            confidence: 0.92,
                            heatmap:
                                "",
                        },
                    ],
                },
            ],
            is_mock: true,
        },
        patient: {
            id: 123,
            age: 62,
            gender: "Male",
            knownIllnesses: ["Covid19", "Pneumonia"],
            symptoms: ["Cough", "Fever"],
            orthancIDs: [],
        },
    };

    let result = $derived($analysisResult || defaultResult);
    let analysis = $derived(result.analysis ?? {});
    let patient = $derived(result.patient ?? {});

    let metadata = $derived($patientMetadata || patient);

    let predictions: Prediction[] = $derived(analysis.predictions ?? []);
    let imageResults: ImageResult[] = $derived(analysis.image_results ?? []);

    let imageIds = $derived(
        $uploadedFileUrls.length > 0
            ? $uploadedFileUrls.map((url) => `png:${url}`)
            : [
                  "png:/example1.png",
                  "png:/example2.png",
                  "png:/example3.png",
                  "png:/example4.png",
              ],
    );

    let threshold = $state(0);

    let filteredPredictions: Prediction[] = $derived(
        predictions.filter((p) => p.confidence * 100 >= threshold),
    );

    let filteredImageResults: ImageResult[] = $derived(
        imageResults
            .map((r) => ({
                ...r,
                predictions: r.predictions.filter(
                    (p) => p.confidence * 100 >= threshold,
                ),
            }))
            .filter((r) => r.predictions.length > 0),
    );

    let activeImageIndex = $state(0);
    let activeHeatmapIndex = $state(0);

    $effect(() => {
        if (activeImageIndex >= imageIds.length) {
            activeImageIndex = Math.max(0, imageIds.length - 1);
        }
    });

    $effect(() => {
        activeHeatmapIndex = activeImageIndex;
    });

    function getConfidenceColor(confidence: number): string {
        if (confidence >= 0.95) return "confidence-critical";
        if (confidence >= 0.9) return "confidence-high";
        if (confidence >= 0.85) return "confidence-medium";
        return "confidence-low";
    }

    function getConfidenceBarColor(confidence: number): string {
        if (confidence >= 0.95) return "confidence-critical-bar";
        if (confidence >= 0.9) return "confidence-high-bar";
        if (confidence >= 0.85) return "confidence-medium-bar";
        return "confidence-low-bar";
    }

    async function startNewAnalysis() {
        try {
            await fetch("/api/analysis", { method: "DELETE" });
        } catch (e) {
            console.error("Failed to delete previous data:", e);
        }
        analysisResult.set(null);
        patientMetadata.set(null);
        uploadedFileUrls.set([]);
        goto("/upload");
    }

    let activeImageResult = $derived(
        filteredImageResults.find((r) => r.index === activeHeatmapIndex) ?? null,
    );
</script>

<div class="mt-6 mx-auto w-full max-w-6xl flex flex-col gap-6 px-6 pb-12">
    <div class="flex items-center justify-between border-b pb-4">
        <div>
            <header
                class="text-2xl font-bold tracking-tight flex items-center gap-2"
            >
                Medical Analysis Dashboard
            </header>
            <h2 class="text-muted-foreground mt-1">
                Detailed AI diagnostics based on patient metadata and X-Ray
                imaging
            </h2>
        </div>
        <Button
            variant="default"
            class="flex items-center gap-2"
            onclick={startNewAnalysis}
        >
            <RotateCcw size={16} /> Start New Analysis
        </Button>
    </div>

    {#if result}
        <Item.Root variant="outline" class="flex">
            <Badge variant="secondary" class="h-8 text-md"
                >Patient ID: {patient.id}</Badge
            >
            <Badge variant="secondary" class="h-8 text-md">
                Age: {patient.age}
            </Badge>
            <Badge variant="secondary" class="h-8 text-md">
                Gender: {patient.gender}
            </Badge>
        </Item.Root>

        {#if predictions.length > 0}
            <Item.Root variant="outline" class="flex-col items-stretch p-4">
                <Item.Header class="mb-2">
                    <Item.Title class="text-lg">
                        AI Diagnosis Ranking
                        <Badge variant="secondary" class="text-xs">
                            {filteredPredictions.length} detected
                        </Badge>
                    </Item.Title>
                </Item.Header>
                <Item.Content class="flex items-center gap-3 mb-4">
                    <Label class="whitespace-nowrap">
                        Confidence threshold
                    </Label>
                    <Slider.Root
                        type="single"
                        bind:value={threshold}
                        min={0}
                        max={100}
                        step={1}
                        class="flex-1 slider-thick"
                    />
                    <Label class="min-w-8 text-right">
                        {threshold}%
                    </Label>
                </Item.Content>
                <Item.Content class="flex flex-col gap-3">
                    {#each filteredPredictions as pred, idx}
                        <Tooltip.Root>
                            <Tooltip.Trigger>
                                {#snippet child({ props })}
                                    <Item.Root
                                        {...props}
                                        variant="outline"
                                        class="flex-col items-stretch p-3 {getConfidenceColor(
                                            pred.confidence,
                                        )}"
                                    >
                                        <Item.Header class="mb-2">
                                            <Item.Title>
                                                <span
                                                    class="text-xs font-bold w-6 h-6 rounded-full bg-background inline-flex items-center justify-center"
                                                >
                                                    {idx + 1}
                                                </span>
                                                {pred.class}
                                            </Item.Title>
                                            <span class="font-bold text-sm">
                                                {(
                                                    pred.confidence * 100
                                                ).toFixed(1)}%
                                            </span>
                                        </Item.Header>
                                        <Progress
                                            value={pred.confidence * 100}
                                            max={100}
                                            class="h-2 mb-2 bg-muted {getConfidenceBarColor(
                                                pred.confidence,
                                            )}"
                                        />
                                        {#if pred.reason}
                                            <Item.Description class="text-xs opacity-80">
                                                {pred.reason}
                                            </Item.Description>
                                        {/if}
                                    </Item.Root>
                                {/snippet}
                            </Tooltip.Trigger>
                            {#if pred.reason}
                                <Tooltip.Content>
                                    <p>{pred.reason}</p>
                                </Tooltip.Content>
                            {/if}
                        </Tooltip.Root>
                    {/each}
                </Item.Content>
                {#if analysis.model_version}
                    <p class="text-xs text-muted-foreground mt-3">
                        Model: {analysis.model_version}
                    </p>
                {/if}
            </Item.Root>
        {:else}
            <Item.Root
                variant="outline"
                class="flex-col items-center justify-center p-6 text-muted-foreground"
            >
                <Stethoscope size={24} class="mx-auto mb-2 opacity-50" />
                <p>No significant findings detected.</p>
            </Item.Root>
        {/if}

        <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div class="lg:col-span-2 flex flex-col">
                <div
                    class="border rounded-xl flex flex-col relative overflow-hidden"
                >
                    <Item.Root>
                        <Item.Description class="flex items-center gap-1.5">
                            <FileDigit size={14} /> PNG Medical Viewport
                        </Item.Description>
                        <Item.Description class="flex items-center">
                            <Badge variant="outline">
                                {#if $uploadedFileUrls.length > 0}
                                    {$uploadedFileUrls.length} File(s) Uploaded
                                {:else}
                                    Example Images (Mock)
                                {/if}
                            </Badge>
                            {#if imageIds.length > 1}
                                <Separator orientation="vertical" class="h-3" />
                                <Badge variant="default">
                                    {activeImageIndex + 1} / {imageIds.length}
                                </Badge>
                            {/if}
                        </Item.Description>
                    </Item.Root>
                    <Item.Media>
                        {#if imageIds.length > 0}
                            <CornerstoneViewport
                                {imageIds}
                                viewportId="result-viewport"
                                bind:activeImageIndex
                            />
                        {/if}
                    </Item.Media>
                    {#if imageIds.length >= 1}
                        <Item.Footer class="bg-card border-t">
                            <ImageBar
                                {imageIds}
                                activeIndex={activeImageIndex}
                                onselect={(i) => (activeImageIndex = i)}
                            />
                        </Item.Footer>
                    {/if}
                </div>
                <Item.Description class="italic px-2 text-xs">
                    * Interactive Viewport: Left-click and drag to adjust window
                    level (contrast), right-click and drag to zoom, wheel to
                    scroll stack.
                </Item.Description>
            </div>

            <div class="flex flex-col gap-4">
                <Item.Root variant="outline">
                    <Item.Header>
                        <Item.Title>Known Illnesses</Item.Title>
                    </Item.Header>
                    <Item.Content class="flex flex-wrap gap-2">
                        {#each patient.knownIllnesses ?? metadata.knownIllnesses ?? [] as illness}
                            <Badge
                                variant="outline"
                                class="illness-badge"
                            >
                                {illness}
                            </Badge>
                        {/each}
                    </Item.Content>
                </Item.Root>

                <Item.Root variant="outline">
                    <Item.Header>
                        <Item.Title>Known Symptoms</Item.Title>
                    </Item.Header>
                    <Item.Content class="flex flex-wrap gap-2">
                        {#each patient.symptoms ?? metadata.symptoms ?? [] as symptom}
                            <Badge
                                variant="outline"
                                class="symptom-badge"
                            >
                                {symptom}
                            </Badge>
                        {/each}
                    </Item.Content>
                </Item.Root>
            </div>
        </div>
        <HeatmapBar imageResults={filteredImageResults} />
        <Chat />
    {:else}
        <Item.Root variant="outline" class="bg:primary">
            <Item.Content
                class="flex flex-col items-center justify-center p-8 text-center"
            >
                <div
                    class="w-12 h-12 rounded-full bg-muted flex items-center justify-center mb-4"
                >
                    <Stethoscope size={24} class="text-muted-foreground" />
                </div>
                <Item.Title class="text-lg">No Results Available</Item.Title>
                <Item.Description class="max-w-md mt-2">
                    Please upload an X-Ray file and enter patient metadata to
                    generate an AI diagnostics report.
                </Item.Description>
                <Button
                    class="mt-6 flex items-center gap-2"
                    onclick={() => goto("/upload")}
                >
                    <Undo2 size={16} /> Back to Upload
                </Button>
            </Item.Content>
        </Item.Root>
    {/if}
</div>
